<template><div class="login-page"><header><BrandMark/><span class="muted">{{auth.siteName}}</span></header><main class="login-main"><section class="login-visual"><div class="login-copy"><h1>校园低空监测平台</h1><p>双目感知<span>·</span>三维定位<span>·</span>事件追溯</p></div><img src="@/assets/campus-login.png" alt="" class="campus-art"/></section><section class="login-card" :class="{'is-setup':auth.setupRequired}"><h2>{{auth.setupRequired?'创建管理员':'登录云瞳'}}</h2><form @submit.prevent="submit"><label class="form-field">账号<div class="input-icon"><UserRound :size="18"/><input v-model="username" required autocomplete="username" placeholder="请输入账号" maxlength="40"/></div></label><label v-if="auth.setupRequired" class="form-field">显示名称<input v-model="displayName" maxlength="80" required/></label><label class="form-field">密码<div class="input-icon"><LockKeyhole :size="18"/><input v-model="password" :type="showPassword?'text':'password'" required :minlength="auth.setupRequired?8:undefined" maxlength="128" :autocomplete="auth.setupRequired?'new-password':'current-password'" :placeholder="auth.setupRequired?'至少 8 个字符':'请输入密码'"/><button type="button" class="icon-button" @click="showPassword=!showPassword" :aria-label="showPassword?'隐藏密码':'显示密码'"><component :is="showPassword?Eye:EyeOff" :size="17"/></button></div></label><label class="remember"><input v-model="remember" type="checkbox"/>记住账号</label><p v-if="error" class="error-banner" role="alert">{{error}}</p><button v-if="!ready" type="button" class="btn" :disabled="busy" @click="connect">重新连接</button><button class="btn primary login-submit" :disabled="busy||!ready"><LoaderCircle v-if="busy" class="spin" :size="18"/>{{busy?'正在连接…':auth.setupRequired?'创建并进入':'登录'}}<ArrowRight v-if="!busy" :size="17"/></button></form><p class="contact-note">账号申请与密码重置请联系本单位管理员</p></section></main><footer>© {{new Date().getFullYear()}} 云瞳 AIRSPACE<span>V2.0</span></footer></div></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{useRouter,useRoute}from'vue-router';import{UserRound,LockKeyhole,Eye,EyeOff,ArrowRight,LoaderCircle}from'lucide-vue-next';import BrandMark from '@/components/BrandMark.vue';import{useAuthStore}from'@/stores/auth';
const auth=useAuthStore(),router=useRouter(),route=useRoute();const username=ref(localStorage.getItem('yuntong.username')||''),password=ref(''),displayName=ref('系统管理员'),remember=ref(!!username.value),showPassword=ref(false),busy=ref(false),error=ref(''),ready=ref(false);
async function connect(){busy.value=true;error.value='';try{await auth.refresh();ready.value=true}catch{error.value='无法连接服务，请检查后端是否启动。'}finally{busy.value=false}}onMounted(connect);
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await auth.login(username.value,password.value,displayName.value);if(remember.value)localStorage.setItem('yuntong.username',username.value);else localStorage.removeItem('yuntong.username');const redirect=String(route.query.redirect||'/home');await router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')?redirect:'/home')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
